import sys
ALLOWED = {"math", "json"}
class Gate:
    def find_module(self, name, path=None):
        if name.split(".")[0] not in ALLOWED:
            raise ImportError(f"blocked: {name}")
        return None  # allowed: fall through to the normal finders
sys.meta_path.insert(0, Gate())
gate = Gate()
verdicts = {}
for mod in ["math", "json", "os", "socket"]:
    try:
        gate.find_module(mod); verdicts[mod] = "admitted"
    except ImportError as e: verdicts[mod] = str(e)
sys.meta_path.pop(0)
print(verdicts)
assert verdicts["math"] == "admitted" and verdicts["os"].startswith("blocked")
